// SPDX-License-Identifier: MIT
// Roostcall (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/roostcall.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "roostcall:<seed>:<difficulty>") and the only draws are randrange at setup; nothing is random after. Byte parity
// goes through engines/unreal/core-test/roostcall_parity.txt (roostcall_core_test.cpp), generated by
// tools/minigames/roostcall_parity.py.
//
// Rules: an S x S yard; the whistler starts north-west, the roost is the 2 x 2 south-east corner, birds start out of
// the whistler's reach. Each turn the whistler moves one cell or waits; then every bird within ScareRange (Chebyshev)
// takes the open neighbouring cell farthest from the whistler (Chebyshev, then Manhattan, then n/e/s/w order) if it
// is strictly farther than where it stands; birds move in index order and see earlier birds' new cells. A bird in
// the roost perches (leaves the yard, counts as settled). All settled wins (+BirdScore each + turns left); dusk loses.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdlib>
#include <string>
#include <utility>
#include <vector>

namespace daedalus { namespace roostcall {

inline const char* GameId() { return "roostcall"; }
inline const char* Title() { return "Roostcall"; }

constexpr int ScareRange = 2, Roost = 2, BirdScore = 10;
constexpr int MaxSize = 12;

struct Difficulty { const char* Name; int Size; int Birds; int Turns; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 6, 3, 16 }, { "normal", 7, 4, 30 }, { "hard", 8, 5, 48 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

/** Moves in the rules' order: n, e, s, w, then wait. Flee ties and the BFS both follow this order. */
enum class Move : int { N = 0, E, S, W, Wait };
constexpr int MoveCount = 5;
inline const char* MoveName(Move M) { static const char* Names[] = { "n", "e", "s", "w", "wait" }; return Names[static_cast<int>(M)]; }
inline bool MoveFromName(const std::string& Name, Move& Out)
{
	for (int I = 0; I < MoveCount; ++I) if (Name == MoveName(static_cast<Move>(I))) { Out = static_cast<Move>(I); return true; }
	return false;
}
inline int MoveDR(Move M) { static const int D[] = { -1, 0, 1, 0, 0 }; return D[static_cast<int>(M)]; }
inline int MoveDC(Move M) { static const int D[] = { 0, 1, 0, -1, 0 }; return D[static_cast<int>(M)]; }

struct Cell { int R = 0, C = 0; bool operator==(const Cell& O) const { return R == O.R && C == O.C; } bool operator!=(const Cell& O) const { return !(*this == O); } };
inline int Chebyshev(Cell A, Cell B) { return std::max(std::abs(A.R - B.R), std::abs(A.C - B.C)); }
inline int Manhattan(Cell A, Cell B) { return std::abs(A.R - B.R) + std::abs(A.C - B.C); }

struct Game
{
	const Difficulty* Diff = nullptr;
	Cell Whistler;
	std::vector<Cell> Birds;   // unsettled birds, in draw order (perched birds are removed)
	int Turns = 0, Settled = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadMove, OffYard, BirdThere, GameOver };

	int Size() const { return Diff ? Diff->Size : 0; }
	bool Inside(Cell X) const { return X.R >= 0 && X.R < Size() && X.C >= 0 && X.C < Size(); }
	bool InRoost(Cell X) const { return X.R >= Size() - Roost && X.C >= Size() - Roost; }
	int BirdAt(Cell X) const { for (size_t I = 0; I < Birds.size(); ++I) if (Birds[I] == X) return static_cast<int>(I); return -1; }
	/** Manhattan distance to the nearest roost cell. */
	int RoostDistance(Cell X) const { return std::max(0, (Size() - Roost) - X.R) + std::max(0, (Size() - Roost) - X.C); }

	/** PrismGame.start + Game.setup. False on an unknown difficulty. Draw order: bird rows and columns in pairs. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Size > MaxSize) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		const int S = Diff->Size;
		Whistler = { 0, 0 };
		Birds.clear();
		while (static_cast<int>(Birds.size()) < Diff->Birds)
		{
			const int R = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			const int C = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			const Cell B{ R, C };
			if (B == Whistler || InRoost(B) || BirdAt(B) >= 0) continue;
			if (Chebyshev(B, Whistler) <= ScareRange) continue;   // birds start out of the whistler's reach
			Birds.push_back(B);
		}
		Turns = Diff->Turns; Settled = 0;
		return true;
	}

	/** Game.flee_step: where bird I steps with the whistler at `From`; false when it stays. */
	bool FleeStep(int I, Cell From, Cell& To) const
	{
		const Cell B = Birds[static_cast<size_t>(I)];
		if (Chebyshev(B, From) > ScareRange) return false;
		int BestCheb = Chebyshev(B, From), BestMan = Manhattan(B, From);
		bool Found = false;
		for (int M = 0; M < 4; ++M)
		{
			const Cell X{ B.R + MoveDR(static_cast<Move>(M)), B.C + MoveDC(static_cast<Move>(M)) };
			if (!Inside(X) || BirdAt(X) >= 0 || X == From) continue;
			const int Cheb = Chebyshev(X, From), Man = Manhattan(X, From);
			if (Cheb > BestCheb || (Cheb == BestCheb && Man > BestMan))   // strictly farther; first in n/e/s/w order wins a tie
			{
				BestCheb = Cheb; BestMan = Man; To = X; Found = true;
			}
		}
		return Found;
	}

	/** Game.act. `Flew`, `Perched` and `Result` mirror the Python result text. */
	Act Step(Move M, int& Flew, int& Perched, std::string& Result)
	{
		Flew = Perched = 0;
		if (Over) return Act::GameOver;
		const Cell Next{ Whistler.R + MoveDR(M), Whistler.C + MoveDC(M) };
		if (!Inside(Next)) return Act::OffYard;
		if (BirdAt(Next) >= 0) return Act::BirdThere;
		Whistler = Next;
		for (size_t I = 0; I < Birds.size(); ++I)
		{
			Cell To;
			if (FleeStep(static_cast<int>(I), Whistler, To)) { Birds[I] = To; ++Flew; }
		}
		std::vector<Cell> Remaining;
		for (const Cell& B : Birds) { if (InRoost(B)) ++Perched; else Remaining.push_back(B); }
		Birds.swap(Remaining);
		Settled += Perched;
		--Turns;
		const std::string Head = std::string(MoveName(M)) + ": " + std::to_string(Flew) + " flew, ";
		if (Birds.empty())
		{
			Score = BirdScore * Settled + Turns;
			Over = Won = true;
			Result = Head + "every bird is home";
			return Act::Ok;
		}
		if (Turns <= 0)
		{
			Score = BirdScore * Settled;
			Over = true; Won = false;
			Result = Head + "dusk falls with " + std::to_string(Settled) + " home";
			return Act::Ok;
		}
		Result = Head + std::to_string(Perched) + " perched, " + std::to_string(Settled) + " home";
		return Act::Ok;
	}

	/** Game._walk_distances: breadth-first walking distance from the whistler, avoiding birds; -1 = unreachable. */
	void WalkDistances(std::array<std::array<int, MaxSize>, MaxSize>& Dist) const
	{
		for (auto& Row : Dist) Row.fill(-1);
		std::array<Cell, MaxSize * MaxSize> Queue{};
		int Head = 0, Tail = 0;
		Queue[Tail++] = Whistler;
		Dist[static_cast<size_t>(Whistler.R)][static_cast<size_t>(Whistler.C)] = 0;
		while (Head < Tail)
		{
			const Cell From = Queue[Head++];
			for (int M = 0; M < 4; ++M)
			{
				const Cell X{ From.R + MoveDR(static_cast<Move>(M)), From.C + MoveDC(static_cast<Move>(M)) };
				if (!Inside(X) || Dist[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] >= 0 || BirdAt(X) >= 0) continue;
				Dist[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] = Dist[static_cast<size_t>(From.R)][static_cast<size_t>(From.C)] + 1;
				Queue[Tail++] = X;
			}
		}
	}

	/** Game._path_first_step: the first move of the shortest walk (n/e/s/w order) to `Goal`; Wait when already there. */
	bool FirstStepTo(Cell Goal, Move& First) const
	{
		if (Goal == Whistler) { First = Move::Wait; return true; }
		std::array<std::array<std::uint8_t, MaxSize>, MaxSize> Via{};   // 0 unvisited, 1 start, 2 + move index
		std::array<std::array<Cell, MaxSize>, MaxSize> Prev{};
		std::array<Cell, MaxSize * MaxSize> Queue{};
		int Head = 0, Tail = 0;
		Queue[Tail++] = Whistler;
		Via[static_cast<size_t>(Whistler.R)][static_cast<size_t>(Whistler.C)] = 1;
		while (Head < Tail)
		{
			const Cell From = Queue[Head++];
			for (int M = 0; M < 4; ++M)
			{
				const Cell X{ From.R + MoveDR(static_cast<Move>(M)), From.C + MoveDC(static_cast<Move>(M)) };
				if (!Inside(X) || Via[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] != 0 || BirdAt(X) >= 0) continue;
				Via[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] = static_cast<std::uint8_t>(2 + M);
				Prev[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] = From;
				if (X == Goal)
				{
					Cell Cur = X; int LastMove = M;
					while (Prev[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)] != Whistler)
					{
						Cur = Prev[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)];
						LastMove = Via[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)] - 2;
					}
					First = static_cast<Move>(LastMove);
					return true;
				}
				Queue[Tail++] = X;
			}
		}
		return false;
	}

	/**
	 * Game.demo_action: herd the bird nearest the roost (index breaks ties). Spots are reachable cells within scare
	 * range of it, ranked by the bird's roost distance after the flight they would cause, then walking distance,
	 * row, column. Pass 1 takes only flights that bring the bird nearer; pass 2 also allows an equal-distance slide
	 * east or south. Waiting on the chosen spot makes the bird fly; with no spot for any bird the whistler waits.
	 */
	Move DemoAction() const
	{
		const int S = Size();
		std::array<std::array<int, MaxSize>, MaxSize> Dist{};
		WalkDistances(Dist);
		std::vector<int> Order(Birds.size());
		for (size_t I = 0; I < Order.size(); ++I) Order[I] = static_cast<int>(I);
		std::stable_sort(Order.begin(), Order.end(), [&](int A, int B) { return RoostDistance(Birds[static_cast<size_t>(A)]) < RoostDistance(Birds[static_cast<size_t>(B)]); });
		for (int Pass = 0; Pass < 2; ++Pass)
		{
			const bool AllowSlide = Pass == 1;
			for (int I : Order)
			{
				const Cell B = Birds[static_cast<size_t>(I)];
				const int Now = RoostDistance(B);
				bool Found = false; int BestKey[4] = { 0, 0, 0, 0 }; Cell Spot;
				for (int R = std::max(0, B.R - ScareRange); R < std::min(S, B.R + ScareRange + 1); ++R)
					for (int C = std::max(0, B.C - ScareRange); C < std::min(S, B.C + ScareRange + 1); ++C)
					{
						const int Walk = Dist[static_cast<size_t>(R)][static_cast<size_t>(C)];
						if (Walk < 0) continue;
						Cell To;
						if (!FleeStep(I, { R, C }, To)) continue;
						const int After = RoostDistance(To);
						const bool Nearer = After < Now;
						const bool Slide = After == Now && (To.R > B.R || To.C > B.C);
						if (!(Nearer || (AllowSlide && Slide))) continue;
						const int Key[4] = { After, Walk, R, C };
						if (!Found || std::lexicographical_compare(Key, Key + 4, BestKey, BestKey + 4))
						{
							Found = true; std::copy(Key, Key + 4, BestKey); Spot = { R, C };
						}
					}
				if (!Found) continue;
				Move First = Move::Wait;
				if (Spot == Whistler) return Move::Wait;
				if (FirstStepTo(Spot, First)) return First;
				return Move::Wait;   // Python's _path_first_step returned None: unreachable, which the distance map rules out
			}
		}
		return Move::Wait;
	}

	static std::string CellsString(const std::vector<Cell>& V)
	{
		if (V.empty()) return "-";
		std::string Out;
		for (size_t I = 0; I < V.size(); ++I) { if (I) Out.push_back(';'); Out += std::to_string(V[I].R) + "," + std::to_string(V[I].C); }
		return Out;
	}
};

} } // namespace daedalus::roostcall
